"""Helpers shared by the case modules: one vector = input → model → projected expectation.

A case module is `cases/<topic>_cases.py` and exposes FILES = [(relative path, thunk)], where
the path is relative to testdata/vectors/ and thunk() returns the file document (file_doc).
gen_social.py imports every case module.
"""

from __future__ import annotations

import json

from lessdugin_ref.common import NS
from lessdugin_ref.fold import fold_vector_input
from lessdugin_ref.projections import DEFAULT_FIELDS, project

GENERATED_BY = ("Generated by testdata/vectors/social-ref/gen_social.py from the reference model "
                "(testdata/vectors/social-ref/lessdugin_ref); do not edit by hand.")


def vector(kind: str, name: str, fold_input: dict, *, fields=None, extra_fields=(), query=None,
           note=None, invalid=None, expect=None) -> dict:
    """Build one vector.

    fields:  the projection fields to assert (default: DEFAULT_FIELDS[kind]) plus extra_fields.
    invalid: {uri: rule} — the records that are deliberately invalid, with their first failing
             rule in the model; every other record must be valid, and the note must name each
             rule (vectors never assert rule IDs: NOTES.md).
    expect:  {field: value} hand-derived expectations, checked against the model's output so
             that a model regression is caught (they are not written to the file separately).
    """
    inp = {"fold": fold_input}
    if query is not None:
        inp["query"] = query
    inp = json.loads(json.dumps(inp))            # the model reads exactly what is written
    view = fold_vector_input(inp)
    invalid = invalid or {}
    for u, v in view.validity.items():
        if u in invalid:
            assert not v.valid and v.rule == invalid[u], (name, u, v, invalid[u])
            assert note and invalid[u] in note, f"{name}: the note must name rule {invalid[u]}"
        else:
            assert v.valid, (name, u, v)
    names = list(fields if fields is not None else DEFAULT_FIELDS[kind]) + list(extra_fields)
    expected = project(view, kind, names)
    if expect:
        for k, want in expect.items():
            got = expected[k] if k in expected else project(view, kind, [k])[k]
            assert got == want, f"{name}: {k}\n  model: {json.dumps(got, indent=1)}\n  hand:  {json.dumps(want, indent=1)}"
    out = {"name": name, "input": inp, "expected": expected}
    if note:
        out["note"] = note
    return out


def file_doc(behaviour: str, kind: str, description: str, vectors: list, **extra) -> dict:
    names = [v["name"] for v in vectors]
    assert len(names) == len(set(names)), "vector names must be unique within a file"
    return {"behaviour": behaviour, "kind": kind, "ns": NS,
            "description": description + " " + GENERATED_BY, "vectors": vectors, **extra}
